  const isFinished = (spec: PlaywrightSpec): boolean => finishedLines.includes(spec.line);

  const problems = [
    ...finishedLines
      .filter((line) => !specs.some((spec) => spec.line === line))
      .map((line) => `The finished test at line ${line} did not run.`),
